output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles, where the shopper must pass between shelves by hand.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_hand_aisle_with_cart",
    "text": "A shopper must not move from an open aisle into a single-file hand-shopping aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "handShoppingAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterHandShoppingAisleWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "handShoppingAisle",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterHandShoppingAisleWithCart"
    }
  },
  {
    "id": "park_cart_at_hand_aisle_mouth",
    "text": "Upon arriving with a cart at the mouth of a single-file hand-shopping aisle, the shopper is obliged to park the cart there before proceeding.",
    "abstraction": {
      "state_properties": {
        "handAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "handShoppingAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "arriveAtHandAisleMouthWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": {
            "and": [
              "handAisleMouth",
              "hasCart"
            ]
          }
        },
        "parkCartAtHandAisleMouth": {
          "pre": {
            "and": [
              "handAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "handAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtHandAisleMouthWithCart",
      "discharge": "parkCartAtHandAisleMouth"
    }
  },
  {
    "id": "no_cart_item_pick_in_hand_aisle",
    "text": "Items located in single-file hand-shopping aisles must not be taken while holding a cart.",
    "abstraction": {
      "state_properties": {
        "handShelfAccess": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "handShelfAccess"
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_after_hand_aisle",
    "text": "After parking a cart at the mouth of a hand-shopping aisle, the shopper is obliged to return to that mouth and reclaim a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "handAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtHandAisleMouth": {
          "pre": {
            "and": [
              "handAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "handAisleMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "reclaimCartAtHandAisleMouth": {
          "pre": {
            "and": [
              "handAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "handAisleMouth",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtHandAisleMouth",
      "discharge": "reclaimCartAtHandAisleMouth"
    }
  },
  {
    "id": "no_cartless_roaming_outside_allowed_zones",
    "text": "A shopper may move without a cart only in the entrance cart area or in the hand-shopping aisle zone where carts are not allowed.",
    "abstraction": {
      "state_properties": {
        "cartPickupArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "handShoppingAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "handAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessPermittedArea": {
          "or": [
            "cartPickupArea",
            "handShoppingAisle",
            "handAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessPermittedArea"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_block_side_pinch_points",
    "text": "A shopper with a cart must not stop to interact with shelves in narrow side-passage pinch points.",
    "abstraction": {
      "state_properties": {
        "sidePinchPoint": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "sidePinchPoint"
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_shopping",
    "text": "Shelf interactions from open cart-accessible aisles should be performed with the cart, unlike interactions inside hand-shopping aisles.",
    "abstraction": {
      "state_properties": {
        "handShoppingAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "handShoppingAisle"
            },
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfFront",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
